sys_script_include.script:
var MSSCustodyAmendUtils = Class.create();
MSSCustodyAmendUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    selectTaskTemplate: function(tempNum) {
        /* This method is utlilized to select the template and extract description and short 
        description by passing the template number 
        Usage:
        var taskTemplate = new global.JSON.parse(this.selectTaskTemplate('CUSTODYTTMP00110'));
        taskTemplate.description //extract Description
        taskTemplate.shortDescription //extract ShortDescription
        */
        var taskTemplate = new GlideRecord('x_hsb11_mss_c_proc_custody_trade_task_template');
        taskTemplate.addQuery('template_id', tempNum);
        taskTemplate.query();
        if (taskTemplate.next()) {
            var tempContents = {
                "description": taskTemplate.getValue("template_description"),
                "shortDescription": taskTemplate.getValue("template_short_description"),
                "trdTaskType": taskTemplate.getValue('trade_task_type'),
                "templateID": taskTemplate.getValue('sys_id')
            };
            return JSON.stringify(tempContents);
        }
    },

    /* This is created for the UI context menu visibility used in the Amend Context menu*/

    evalMakerAccess: function() {
        var makerAccess = false;

        var grUserGroupMember = new GlideRecord("sys_user_grmember");
        grUserGroupMember.addQuery("user", gs.getUserID());
        grUserGroupMember.addQuery('group.nameLIKEmaker');
        grUserGroupMember.query();
        if (grUserGroupMember.next())
            makerAccess = true;
        return makerAccess;
    },

    evalAmendInputs: function() {
        try {
            var doubleDecimalCurrencies = ['USD', 'EUR', 'GBP'];
            var tripleDecimalCurrencies = ['KWD', 'BHD', 'OMR'];
            var twoDecRegex = /^[0-9]*(\.[0-9]{0,2})?$/;
            var threeDecRegex = /^[0-9]*(\.[0-9]{0,3})?$/;
            var fiveDecRegex = /^[0-9]*(\.[0-9]{0,5})?$/;
            var eightAlphaNumericRegex = /^[a-zA-Z0-9]{8}$/;
            var elevenAlphaNumericRegex = /^[a-zA-Z0-9]{11}$/;
            var twentyFourAlphaNumericRegex = /^[a-zA-Z0-9]{24}$/;
            var fieldRegex = /^[a-zA-Z0-9 ]*$/;
            var accOfClientFieldRegex = /^[a-zA-Z0-9()\/\-?:.,'+ ]+$/;
            var todaysDate = new GlideDate();
            var notifyUser = [];
            var finalCheck = [];
            errorFieldArray = []; //MSSCUSTODY-6872

            var trdSettlementDate = this.getParameter('sysparm_trdSettlementDate');
            var tskAmendDate = this.getParameter('sysparm_taskAmendDate');
            var trdSettmentCurr = this.getParameter('sysparm_trdSettlementCurr');
            var amendCurr = this.getParameter('sysparm_taskAmendCurr');
            var amendSettAmt = this.getParameter('sysparm_taskAmendSettAmt');
            var amendSettCurrency = this.getParameter('sysparm_amendSettCurrency');
            var amendLocationCode = this.getParameter('sysparm_taskAmendLocationCode');
            var tradeId = this.getParameter('sysparm_tradeId');
            var amendGdiIndicator = this.getParameter('sysparm_gdiIndicator');
            var placeOfSettlementBic = this.getParameter('sysparm_placeOfSettlementBic');
            var amendScriptHoldIndicator = this.getParameter('sysparm_amendScriptHoldIndicator');
            var amendCashHoldIndicator = this.getParameter('sysparm_amendCashHoldIndicator');
            var amendDelivererReceivererBic = this.getParameter('sysparm_amendDelivererReceivererBic');
            var amendDealPrice = this.getParameter('sysparm_amendDealPrice');
            var amendDealCurrency = this.getParameter('sysparm_amendDealCurrency');
            var trdCashAccId = this.getParameter('sysparm_trdCashAccId');
            var amendBuyerSellerBic = this.getParameter('sysparm_amendBuyerSellerBic');
            var amendCustomerReference = this.getParameter('sysparm_amendCustomerReference');
            var amendSuspenseAccNum = this.getParameter('sysparm_amendSuspenseAccNum');
            var amendSettDate = this.getParameter('sysparm_amendSettDate');
            var amendChargesType = this.getParameter('sysparm_amendChargesType');
            var amendChargesAmt = this.getParameter('sysparm_amendChargesAmt');
            var amendChargesCcy = this.getParameter('sysparm_amendChargesCcy');
            var amendCounterpartySettAccNum = this.getParameter('sysparm_amendCounterpartySettAccNum');
            var amendCounterpartyRef = this.getParameter('sysparm_amendCounterpartyRef');
            var accOfClient = this.getParameter('sysparm_accOfClient');
            var amendSecurityID = this.getParameter('sysparm_amendSecurityID');
            var amendSwitchAccount = this.getParameter('sysparm_amendSwitchAccount');
            var amendCounterpartyCode = this.getParameter('sysparm_amendCounterpartyCode');
            var tradeAmendSecurityID = this.getParameter('sysparm_tradeAmendSecurityID');
            var tradeAmendSwitchAccount = this.getParameter('sysparm_tradeAmendSwitchAccount');
            var tradeAmendCounterpartyCode = this.getParameter('sysparm_tradeAmendCounterpartyCode');
            var amendReceivererBic = this.getParameter('sysparm_amendReceivererBic'); //7133
            var amendBuyerBic = this.getParameter('sysparm_amendBuyerBic'); //7133
            var amendSWH = this.getParameter('sysparm_amendSWH'); //7910
            var switchRef = this.getParameter('sysparm_switchRef'); //8173
            var tradeSwitchRef = this.getParameter('sysparm_tradeSwitchRef'); //8173
            var amendFA = this.getParameter('sysparm_amendFA'); //8184

            var legacyStatus = this.getParameter('sysparm_legacyStatus');
            var transactionType = this.getParameter('sysparm_transactionType');
            var legacySubStatus = this.getParameter('sysparm_legacySubStatus');
            var switchIndicator = this.getParameter('sysparm_switchIndicator');
            var owningBusiness = this.getParameter('sysparm_owningBusiness');
            var convertToAccSwitching = this.getParameter('sysparm_convertToAccSwitching');
            var arrayFlag = this.getParameter('sysparm_arrayFlag');
            //gs.info("amend 86 accOfClient= " + accOfClient);

            var counterpartyCode = tradeAmendCounterpartyCode ? tradeAmendCounterpartyCode[0] == 'C' : false;

            var data = [];
            data = trdCashAccId.split(' ');
            // gs.info("amend 92 data =" + data);
            var tradeRec = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_trade");
            tradeRec.get(tradeId);
            var tradeDate = tradeRec.trade_date;
            var securitiesData = tradeRec.securities_account;
            var linkIndicator = tradeRec.link_indicator;

            var locCode = new GlideRecord("x_hsb11_mss_c_proc_custody_location_code"); //7910
            locCode.get(amendLocationCode);
            var locDisplayValue = locCode.location_code;

            // gs.info("amend 96 tradeDate =" + tradeDate);
            //gs.addInfoMessage('From script Include Amend: ' + " trdSettlementDate " + trdSettlementDate + " tskAmendDate " + tskAmendDate + " amendCurr " + amendCurr + " amendSettAmt " + amendSettAmt);

            notifyUser.push("<a><strong>" + "Please review the below inputs as suggessted to proceed with amendment" + "</strong></a><br\>");
            //gs.info("amend 100 ");
            try {
                //gs.info("amend 102 in try ");
                // MSSCUSTODY-6226


                if ((legacyStatus == 'PRPR' || legacyStatus == 'CODE' || (legacyStatus == 'PAPP' && legacySubStatus == 'RCP')) && (amendSecurityID == '' || amendSecurityID == null) && (tradeAmendSecurityID == '' || tradeAmendSecurityID == null)) {
                    notifyUser.push("Security ID (SEC ID) is a Mandatory field. Please enter a value before submitting. <br\>");
                    errorFieldArray.push('amendSecurityID');
                }

                if ((legacyStatus == 'PRPR' || legacyStatus == 'CODE' || (legacyStatus == 'PAPP' && legacySubStatus == 'RCP')) && (amendCounterpartyCode == '' || amendCounterpartyCode == null) && (tradeAmendCounterpartyCode == '' || tradeAmendCounterpartyCode == null) && (switchIndicator == 'N' && convertToAccSwitching != 'Y')) {
                    notifyUser.push("Counterparty Code is a Mandatory field. Please enter a value before submitting. <br\>");
                    errorFieldArray.push('amendCounterpartyCode');
                }

                if ((legacyStatus == 'PRPR') && (owningBusiness == 'DCC HK') && (accOfClient == '' || accOfClient == null) && (amendCounterpartyCode ? amendCounterpartyCode[0] == 'C' : counterpartyCode) && (convertToAccSwitching != 'Y')) {
                    notifyUser.push("A/c of Client is a Mandatory field. Please enter a value before submitting. <br\>");
                    errorFieldArray.push('accOfClient');
                }
                // if ((amendSuspenseAccNum == '' || amendSuspenseAccNum == null) && (switchIndicator == 'Y' || convertToAccSwitching == 'Y') && (transactionType == 'RVP' || transactionType == 'DVP')) {
                //     notifyUser.push("Suspense Account Number is a Mandatory field. Please enter a value before submitting. <br\>");
                //     errorFieldArray.push('amendSuspenseAccNum');
                // }


                var request;
                var responseBody;
                var responseObj;
                var bulkRecord;

                if (amendSecurityID != '' && amendSecurityID != null) {
                    request = new sn_ws.RESTMessageV2('x_hsb11_hsbc_mss_o.MSS Remote Table Ondemand API Send', 'Get Remote Table Records');
                    request.setStringParameterNoEscape('mssRemoteTableOnDemandenv', gs.getProperty('x_hsb11_hsbc_mss_o.hsbcmss_el_custodyRemoteTableonDemand_api_url') + 'instruments');
                    request.setStringParameterNoEscape('mssRemoteTableOnDemandToken', gs.getProperty('x_hsb11_mss_c_swft.hsbcmss_el_custodySwiftonDemand_api_token'));
                    request.setQueryParameter('siteCode', gs.getSession().getClientData('siteCode'));
                    request.setQueryParameter('instrumentAlternateGhssIdentifier', amendSecurityID);
                    response = request.execute();
                    responseBody = response.getBody();
                    responseObj = JSON.parse(responseBody);
                    if (responseObj.status == '200' && responseObj.data.length == 1) {
                        // do nothing
                    } else if (responseObj.status == '200' && responseObj.data.length == 0) {
                        notifyUser.push("Security ID (SEC ID) (" + amendSecurityID + ") entered is Invalid. <br\>");
                    } else if (responseObj.status == '200' && responseObj.data.length > 1) {
                        notifyUser.push("There are more than one record for the Security ID (SEC ID) (" + amendSecurityID + ") entered. <br\>");
                    } else if (responseObj.status.toString().charAt(0) == '4' || responseObj.status.toString().charAt(0) == '5') {
                        notifyUser.push("Unexpected Error at external system for Security ID (SEC ID) (" + amendSecurityID + "). <br\>");
                    } else {
                        endSleep = new GlideDuration().getNumericValue() + 5000;
                        while (new GlideDuration().getNumericValue() < endSleep) {
                            //wait 
                        }
                        if (responseObj.status == '200' && responseObj.data.length == 0) {
                            notifyUser.push("Security ID (SEC ID) (" + amendSecurityID + ") entered is Invalid. <br\>");
                        } else if (responseObj.status == '200' && responseObj.data.length > 1) {
                            notifyUser.push("There are more than one record for the Security ID (SEC ID) (" + amendSecurityID + ") entered. <br\>");
                        } else if (responseObj.status.toString().charAt(0) == '4' || responseObj.status.toString().charAt(0) == '5') {
                            notifyUser.push("Unexpected Error at external system for Security ID (SEC ID) (" + amendSecurityID + "). <br\>");
                        } else {
                            notifyUser.push("No response received from external system for Security ID (SEC ID) (" + amendSecurityID + "). <br\>");
                        }
                    }
                }

                if (amendSwitchAccount != '' && amendSwitchAccount != null) {
                    request = new sn_ws.RESTMessageV2('x_hsb11_hsbc_mss_o.MSS Remote Table Ondemand API Send', 'Get Remote Table Records');
                    request.setStringParameterNoEscape('mssRemoteTableOnDemandenv', gs.getProperty('x_hsb11_hsbc_mss_o.hsbcmss_el_custodyRemoteTableonDemand_api_url') + 'accounts');
                    request.setStringParameterNoEscape('mssRemoteTableOnDemandToken', gs.getProperty('x_hsb11_mss_c_swft.hsbcmss_el_custodySwiftonDemand_api_token'));
                    request.setQueryParameter('siteCode', gs.getSession().getClientData('siteCode'));
                    request.setQueryParameter('safekeepingAccountIdentification', amendSwitchAccount);
                    response = request.execute();
                    responseBody = response.getBody();
                    responseObj = JSON.parse(responseBody);
                    if (responseObj.status == '200' && responseObj.data.length == 1) {
                        // do nothing
                    } else if (responseObj.status == '200' && responseObj.data.length == 0) {
                        notifyUser.push("Switch Account (" + amendSwitchAccount + ") entered is Invalid. <br\>");
                    } else if (responseObj.status == '200' && responseObj.data.length > 1) {
                        notifyUser.push("There are more than one record for the Switch Account (" + amendSwitchAccount + ") entered. <br\>");
                    } else if (responseObj.status.toString().charAt(0) == '4' || responseObj.status.toString().charAt(0) == '5') {
                        notifyUser.push("Unexpected Error at external system for Switch Account (" + amendSwitchAccount + "). <br\>");
                    } else {
                        endSleep = new GlideDuration().getNumericValue() + 5000;
                        while (new GlideDuration().getNumericValue() < endSleep) {
                            //wait 
                        }
                        if (responseObj.status == '200' && responseObj.data.length == 0) {
                            notifyUser.push("Switch Account (" + amendSwitchAccount + ") entered is Invalid. <br\>");
                        } else if (responseObj.status == '200' && responseObj.data.length > 1) {
                            notifyUser.push("There are more than one record for the Switch Account (" + amendSwitchAccount + ") entered. <br\>");
                        } else if (responseObj.status.toString().charAt(0) == '4' || responseObj.status.toString().charAt(0) == '5') {
                            notifyUser.push("Unexpected Error at external system for Switch Account (" + amendSwitchAccount + "). <br\>");
                        } else {
                            notifyUser.push("No response received from external system for Switch Account (" + amendSwitchAccount + "). <br\>");
                        }
                    }
                }

                if (amendCounterpartyCode != '' && amendCounterpartyCode != null) {
                    request = new sn_ws.RESTMessageV2('x_hsb11_hsbc_mss_o.MSS Remote Table Ondemand API Send', 'Get Remote Table Records');
                    request.setStringParameterNoEscape('mssRemoteTableOnDemandenv', gs.getProperty('x_hsb11_hsbc_mss_o.hsbcmss_el_custodyRemoteTableonDemand_api_url') + 'counterparties');
                    request.setStringParameterNoEscape('mssRemoteTableOnDemandToken', gs.getProperty('x_hsb11_mss_c_swft.hsbcmss_el_custodySwiftonDemand_api_token'));
                    request.setQueryParameter('siteCode', gs.getSession().getClientData('siteCode'));
                    request.setQueryParameter('partyAlternateGhssIdentifier', amendCounterpartyCode);
                    response = request.execute();
                    responseBody = response.getBody();
                    responseObj = JSON.parse(responseBody);
                    if (responseObj.status == '200' && responseObj.data.length == 1) {
                        // do nothing
                    } else if (responseObj.status == '200' && responseObj.data.length == 0) {
                        notifyUser.push("Counterparty Code (" + amendCounterpartyCode + ") entered is Invalid. <br\>");
                    } else if (responseObj.status == '200' && responseObj.data.length > 1) {
                        notifyUser.push("There are more than one record for the Counterparty Code (" + amendCounterpartyCode + ") entered. <br\>");
                    } else if (responseObj.status.toString().charAt(0) == '4' || responseObj.status.toString().charAt(0) == '5') {
                        notifyUser.push("Unexpected Error at external system for Counterparty Code (" + amendCounterpartyCode + "). <br\>");
                    } else {
                        endSleep = new GlideDuration().getNumericValue() + 5000;
                        while (new GlideDuration().getNumericValue() < endSleep) {
                            //wait 
                        }
                        if (responseObj.status == '200' && responseObj.data.length == 0) {
                            notifyUser.push("Counterparty Code (" + amendCounterpartyCode + ") entered is Invalid. <br\>");
                        } else if (responseObj.status == '200' && responseObj.data.length > 1) {
                            notifyUser.push("There are more than one record for the Counterparty Code (" + amendCounterpartyCode + ") entered. <br\>");
                        } else if (responseObj.status.toString().charAt(0) == '4' || responseObj.status.toString().charAt(0) == '5') {
                            notifyUser.push("Unexpected Error at external system for Counterparty Code (" + amendCounterpartyCode + "). <br\>");
                        } else {
                            notifyUser.push("No response received from external system for Counterparty Code (" + amendCounterpartyCode + "). <br\>");
                        }
                    }
                }

            } catch (e) {
                gs.info('Unexpected error occured in Validating Remote table fields : ' + e.message);
            }

            //Trade Date Check // Check 1
            if (tskAmendDate > amendSettDate) {
                notifyUser.push(" Trade Date should be less than or equal to Settlement date (" + amendSettDate + ")<br\>");
                finalCheck.push('false' + ',');
                errorFieldArray.push("tskAmendDate");
            }
            //Trade Date Check

            //Switch Reference Check   //8173

            if (switchRef == '' && amendSwitchAccount == '' && tradeAmendSwitchAccount == '' && tradeSwitchRef == '' && convertToAccSwitching == 'Y') {
                notifyUser.push("The Switch Reference can not be empty for a switching trade. <br\>");
                finalCheck.push('false' + ',');
                errorFieldArray.push("switchRef");
            }

            //Switch Reference Check

            //FA Check //8184

            if (owningBusiness == 'DCC MY') {
                if (amendCashHoldIndicator == 'N' && (amendFA != 'X' && amendFA != 'T')) {
                    notifyUser.push("FA should be selected as 'X' or 'T' if Cash Hold Indicator is 'N'. <br\>");
                    finalCheck.push('false' + ',');
                    errorFieldArray.push('amendFA');
                } else if ((amendCashHoldIndicator == 'I' || amendCashHoldIndicator == 'S') && amendFA != '') {
                    notifyUser.push("FA should be selected as blank if Cash Hold Indicator is " + amendCashHoldIndicator + "<br\>");
                    finalCheck.push('false' + ',');
                    errorFieldArray.push('amendFA');
                }
            }

            //FA Check 

            //Amend Charges Currency & Amount Mandatory check

            if (amendChargesType == 'U' && (amendChargesAmt == '' || amendChargesCcy == '')) {
                notifyUser.push("The Amend Charges Currency or Amend Charges Amount can not be empty if Amend Charges Type is 'U'. <br\>");
                finalCheck.push('false' + ',');
                if (amendChargesAmt == '') {
                    errorFieldArray.push('amendChargesAmt');

                } else if (amendChargesCcy == '') {
                    errorFieldArray.push('amendChargesCcy');
                }
            }

            //Amend Charges Currency & Amount Mandatory check

            //Amend Charges Currency check

            if (amendChargesCcy != '' && amendChargesCcy != null) {
                var curr = new GlideRecord("fx_currency");
                curr.addQuery('sys_id', amendChargesCcy.toString());
                curr.query();
                if (!(curr.next())) {
                    notifyUser.push("The Amend Charges Currency is invalid. <br\>");
                    finalCheck.push('false' + ',');
                    errorFieldArray.push('amendChargesCcy');

                }
            }

            //Amend Charges Currency check

            //SWH Check   //7910

            if (owningBusiness == 'DCC JP' && (switchIndicator == 'Y' || convertToAccSwitching == 'Y') && locDisplayValue == 'BOJ') {
                if (amendSettDate < todaysDate && amendSWH == '') {
                    notifyUser.push("SWH can not be empty for this trade. <br\>");
                    finalCheck.push('false' + ',');
                    errorFieldArray.push('amendSWH');
                } else if (amendSettDate >= todaysDate && amendSWH != '') { //8128
                    notifyUser.push("Settlement date should be earlier than today if SWH has a value. <br\>");
                    finalCheck.push('false' + ',');
                    errorFieldArray.push('amendSWH');
                }
            }

            //SWH Check

            //Amend Charges Amount check
            if (amendChargesAmt != '' && amendChargesCcy != '') {
                // gs.info("amend 244 ");
                var amendChargesAmt = amendChargesAmt.replace(/[.,]/g, '');
                var curr = new GlideRecord("fx_currency");
                if ((amendChargesAmt.toString() <= 0) || (!(fieldRegex.test(amendChargesAmt)))) {
                    notifyUser.push("Amend Charges Amount can not be zero. <br\>");
                    finalCheck.push('false' + ',');
                    errorFieldArray.push('amendChargesAmt');
                } else if (curr.get(amendChargesCcy)) {
                    var taskCurr = curr.code;
                    if (tripleDecimalCurrencies.indexOf(taskCurr.toString()) > -1) {
                        if (!threeDecRegex.test(amendChargesAmt)) {
                            notifyUser.push("Only three decimal values are allowed for " + taskCurr + "<br\>");
                            finalCheck.push('false' + ',');
                            errorFieldArray.push('amendChargesAmt');
                        }
                    } else if (doubleDecimalCurrencies.indexOf(taskCurr.toString()) > -1) {
                        if (!twoDecRegex.test(amendChargesAmt)) {
                            notifyUser.push("Only two decimal values are allowed for " + taskCurr + "<br\>");
                            finalCheck.push('false' + ',');
                            errorFieldArray.push('amendChargesAmt');
                        }
                    }
                }
            }
            //Amend Charges Amount check

            //Switch Account Check
            if (switchIndicator == 'Y' || convertToAccSwitching == 'Y') {
                if (amendSwitchAccount != '' && amendSwitchAccount != null) {
                    var amendSwitchAccountRegex = this.regexCheck(amendSwitchAccount);
                    var securitiesDataRegex = this.regexCheck(securitiesData);
                    if (amendSwitchAccountRegex == securitiesDataRegex) {
                        notifyUser.push(" Switch Account can not be same as Trade's Securities Account Number. <br\>");
                        finalCheck.push('false' + ',');
                        errorFieldArray.push('amendSwitchAccount');
                    }
                } else if (((amendSwitchAccount == '' || amendSwitchAccount == null) && (tradeAmendSwitchAccount == '' || tradeAmendSwitchAccount == null) && (tradeSwitchRef == '' || tradeSwitchRef == null) && (switchRef == '' || switchRef == null) && convertToAccSwitching == 'Y') || ((amendSwitchAccount == '' || amendSwitchAccount == null) && (tradeAmendSwitchAccount == '' || tradeAmendSwitchAccount == null) && convertToAccSwitching != 'Y')) { //switchRef && tradeSwitchRef added under 8173
                    notifyUser.push("Switch Account is a mandatory field for switching trade. <br\>");
                    finalCheck.push('false' + ',');
                    errorFieldArray.push('amendSwitchAccount');
                }
            }
            //Switch Account Check

            //Settlement Date Check
            //gs.info("amend 267 amendSettDate =" + amendSettDate + " & tradeDate =" + tradeDate);
            if (amendSettDate < tskAmendDate) {
                notifyUser.push(" Settlement Date should be beyond or equal to Trade date (" + tskAmendDate + ")<br\>");
                finalCheck.push('false' + ',');
                errorFieldArray.push("amendSettDate");

            }

            //Settlement Date Check

            //gs.info("amend 274 accOfClient =" + accOfClient);
            //Account of Client Check
            if ((accOfClient != "") && (accOfClient != null)) {
                //gs.info("amend 267 accOfClient in loop= " + accOfClient);
                if (!(accOfClientFieldRegex.test(accOfClient))) {
                    // gs.info("amend 269 accOfClient in regex= " + accOfClient);
                    notifyUser.push("Account of Client can not contain special characters. <br\>");
                    finalCheck.push('false' + ',');
                    errorFieldArray.push('accOfClient');
                }
            }

            //Account of Client Check

            //Script Hold Indicator Check
            //gs.info("amend 287 amendScriptHoldIndicator =" + amendScriptHoldIndicator);
            if (amendScriptHoldIndicator != '' && amendScriptHoldIndicator != null) {
                if (amendScriptHoldIndicator == 'S' && (amendSettDate <= todaysDate) && (owningBusiness != 'DCC JP' && owningBusiness != 'DCC AU')) {
                    notifyUser.push("Scrip hold indicator cannot be 'S' when settlement date is less than or equal to today. <br\>");
                    finalCheck.push('false' + ',');
                    errorFieldArray.push('amendScriptHoldIndicator');
                } else if (linkIndicator == 'Y' && amendScriptHoldIndicator == 'I') {
                    notifyUser.push("Scrip hold indicator cannot be 'I' if trade has Link Indicator value as 'Y'. <br\>");
                    finalCheck.push('false' + ',');
                    errorFieldArray.push('amendScriptHoldIndicator');
                }
            }
            //Script Hold Indicator Check

            //Suspense Account Num Check
            // gs.info("amend 297 amendSuspenseAccNum =" + amendSuspenseAccNum);
            // if (amendSuspenseAccNum != "" && amendSuspenseAccNum != null && switchIndicator != 'Y' && convertToAccSwitching != 'Y') {
            //     if (!twentyFourAlphaNumericRegex.test(amendSuspenseAccNum)) {
            //         notifyUser.push("The Suspense Account Number should be a 24 character value without spaces, dashes or special characters.<br\>");
            //         finalCheck.push('false' + ',');
            //         errorFieldArray.push('amendSuspenseAccNum');
            //     }
            // }

            //Suspense Account Num Check

            // Cash Hold Indicator Check
            //gs.info("amend 308 amendCashHoldIndicator =" + amendCashHoldIndicator);
            if (amendCashHoldIndicator != null && amendCashHoldIndicator != '' && (owningBusiness != 'DCC JP' && owningBusiness != 'DCC AU')) {
                if (amendCashHoldIndicator == 'S' && (amendSettDate <= todaysDate)) {
                    notifyUser.push(" Settlement Date should be beyond today's date for value 'S' in Cash Hold Indicator <br\>");
                    finalCheck.push('false' + ',');
                    errorFieldArray.push('amendCashHoldIndicator');
                }
            }
            // Cash Hold Indicator Check
            //gs.info("amend 316 amendDealPrice =" + amendDealPrice);
            //Deal Price 
            if (amendDealPrice != "" && amendDealPrice != null) {
                if (!fiveDecRegex.test(amendDealPrice)) {
                    notifyUser.push("Only five decimal values are allowed for Deal Price " + "<br\>");
                    finalCheck.push('false' + ',');
                    errorFieldArray.push('amendDealPrice');
                }
            }
            //Deal Price

            //Deal Currency   //commented as a part of MSSCUSTODY-6744

            // if (amendDealCurrency != "" && amendDealCurrency != null) {
            // 	if (amendDealCurrency != amendCurr) {
            // 		notifyUser.push("Deal Currency should be same as Trade's Settlement Amount Currency (" + trdSettmentCurr + ") <br\>");
            // 		finalCheck.push('false' + ',');
            // 	}
            // }

            //Deal Currency 

            //gs.info("amend 337 amendCurr =" + amendCurr);
            //gs.info("amend 338 data[1] =" + data[1]);
            //Settlement Currency Check
            if (amendCurr != "" && amendCurr != null && owningBusiness != 'DCC KR') {
                var cashAccCurrency = data[1].toString();
                var curr = new GlideRecord("fx_currency");
                if (curr.get(amendCurr)) {
                    var taskCurr = curr.code;
                    if (taskCurr != cashAccCurrency) {
                        //notifyUser.push("Trade currency is different<br\>");
                        notifyUser.push("The selected settlement currency is different than the trade currency(" + cashAccCurrency + "). Please verify before proceeding. <br\>");
                        errorFieldArray.push('amendCurr');
                    }
                }
            }
            //Settlement Currency Check

            // //Amend Settlement Currency
            // if(amendSettCurrency != null ){
            // 	var cashAccCurrency = data[1].toString();
            // 	if(cashAccCurrency != amendSettCurrency.toString()){
            // 		notifyUser.push("Settlement currency shoud be same as Cash Account Identification Currency (" + cashAccCurrency + ")<br\>");
            // 	}
            // }
            // //Amend Settlement Currency
            // gs.info("amend 361 amendLocationCode =" + amendLocationCode);
            //location code
            if (amendLocationCode != "" && amendLocationCode != null) {
                var locCode = new GlideRecord("x_hsb11_mss_c_proc_custody_location_code");
                locCode.addQuery('sys_id', amendLocationCode.toString());
                locCode.query();
                if (locCode.next()) {
                    //locCode.get(amendLocationCode);
                    if (locCode.owning_business != tradeRec.owning_business) {
                        notifyUser.push('The location code is invalid for this market. <br\>');
                        finalCheck.push('false' + ',');
                    }
                } else {
                    notifyUser.push('The location code is invalid. <br\>');
                    finalCheck.push('false' + ',');
                }
            }
            //location code check
            //gs.info("amend 376 amendGdiIndicator =" + amendGdiIndicator);
            //GDI Check
            if (amendGdiIndicator != "" && amendGdiIndicator != null) {
                var tradeGDI = tradeRec.gdi_indicator;
                if (owningBusiness.indexOf('HK') > -1 && (switchIndicator == 'Y' || convertToAccSwitching == 'Y') && amendGdiIndicator != 'Not Generate') {
                    notifyUser.push('The GDI Indicator value should only be Not Generate if market is HK.' + "<br\>");
                    finalCheck.push('false' + ',');
                    errorFieldArray.push('amendGdiIndicator');
                } else {
                    if ((tradeGDI == 'Not Generate' && (amendGdiIndicator == 'Auto Generation' || amendGdiIndicator == 'Manual Generation'))) {
                        notifyUser.push('The GDI Indicator value can not be updated to Manual Generation or Auto Generation from Not Generate' + "<br\>");
                        finalCheck.push('false' + ',');
                        errorFieldArray.push('amendGdiIndicator');
                    } else if (tradeGDI == 'Manual Generation' && amendGdiIndicator == 'Auto Generation') {
                        notifyUser.push('The GDI Indicator value can not be updated to Auto Generation from Manual Generation' + "<br\>");
                        finalCheck.push('false' + ',');
                        errorFieldArray.push('amendGdiIndicator');
                    }
                }

            }
            //GDI Check

            //

            //Place of Settlement (BIC) Check
            if (placeOfSettlementBic != "" && placeOfSettlementBic != null) {
                if (!(elevenAlphaNumericRegex.test(placeOfSettlementBic)) && !(eightAlphaNumericRegex.test(placeOfSettlementBic))) {
                    notifyUser.push("The Place of Settlement (BIC) should be eight or eleven alphanumeric value <br\>");
                    finalCheck.push('false' + ',');
                    errorFieldArray.push('placeOfSettlementBic');
                }
            }
            //Place of Settlement (BIC) Check

            //changes under 7133------------START---------//

            //Seller BIC check

            if (amendBuyerSellerBic != "" && amendBuyerSellerBic != null) {
                if (!(elevenAlphaNumericRegex.test(amendBuyerSellerBic)) && !(eightAlphaNumericRegex.test(amendBuyerSellerBic))) {
                    notifyUser.push("The Seller BIC should be eight or eleven alphanumeric value <br\>");
                    finalCheck.push('false' + ',');
                    errorFieldArray.push('amendBuyerSellerBic');
                }
            }

            //Seller BIC check

            //Buyer BIC check

            if (amendBuyerBic != "" && amendBuyerBic != null) {
                if (!(elevenAlphaNumericRegex.test(amendBuyerBic)) && !(eightAlphaNumericRegex.test(amendBuyerBic))) {
                    notifyUser.push("The Buyer BIC should be eight or eleven alphanumeric value <br\>");
                    finalCheck.push('false' + ',');
                    errorFieldArray.push('amendBuyerBic');
                }
            }

            //Buyer BIC check

            //Buyer Deliverer Custodian BIC check

            if (amendDelivererReceivererBic != "" && amendDelivererReceivererBic != null) {
                if (!(elevenAlphaNumericRegex.test(amendDelivererReceivererBic)) && !(eightAlphaNumericRegex.test(amendDelivererReceivererBic))) {
                    notifyUser.push("The Deliverer Custodian BIC should be eight or eleven alphanumeric value <br\>");
                    finalCheck.push('false' + ',');
                    errorFieldArray.push('amendDelivererReceivererBic');
                }
            }

            //Buyer Deliverer/Receiverer Custodian BIC check

            //Buyer Receiverer Custodian BIC check

            if (amendReceivererBic != "" && amendReceivererBic != null) {
                if (!(elevenAlphaNumericRegex.test(amendReceivererBic)) && !(eightAlphaNumericRegex.test(amendReceivererBic))) {
                    notifyUser.push("The Receiverer Custodian BIC should be eight or eleven alphanumeric value <br\>");
                    finalCheck.push('false' + ',');
                    errorFieldArray.push('amendReceivererBic');
                }
            }

            //Buyer Receiverer Custodian BIC check

            //changes under 7133------------END---------//

            //Customer Reference Check

            if ((amendCustomerReference == "") || (!(accOfClientFieldRegex.test(amendCustomerReference)))) {
                if (legacyStatus == 'PAPP' || legacyStatus == 'PRPR' || legacyStatus == 'CODE' || legacyStatus == 'RCP' || legacyStatus == 'CONF' || legacyStatus == 'CLRG' || legacyStatus == 'PCON') {
                    notifyUser.push("Customer Reference can not be empty or can not contain special characters. <br\>");
                    finalCheck.push('false' + ',');
                    errorFieldArray.push('amendCustomerReference');
                }
            }
            //Customer Reference Check

            //Counterparty Reference Check
            if ((amendCounterpartyRef != "" && amendCounterpartyRef != null) && (!(accOfClientFieldRegex.test(amendCounterpartyRef)))) {
                notifyUser.push("Counterparty Reference can not contain special characters. <br\>");
                finalCheck.push('false' + ',');
                errorFieldArray.push('amendCounterpartyRef');
            }
            //Counterparty Reference Check

            //Counterparty Settlement Account Number Check
            //gs.info("amend 416 amendCounterpartyRef = " + amendCounterpartyRef);
            if ((amendCounterpartySettAccNum != "" && amendCounterpartySettAccNum != null) && (!(fieldRegex.test(amendCounterpartySettAccNum)))) {
                notifyUser.push("Counterparty Settlement Account Number can not contain special characters. <br\>");
                finalCheck.push('false' + ',');
                errorFieldArray.push('amendCounterpartySettAccNum');
            }
            //Counterparty Settlement Account Number Check

            //Settlement Amount Check

            if (amendCurr != "" && amendSettAmt != "" && amendCurr != null && amendSettAmt != null) {
                var curr = new GlideRecord("fx_currency");
                amendSettAmt = amendSettAmt.replace(/,/g, "");
                if (curr.get(amendCurr)) {
                    var taskCurr = curr.code;
                    if (tripleDecimalCurrencies.indexOf(taskCurr.toString()) > -1) {
                        if (!threeDecRegex.test(amendSettAmt)) {
                            notifyUser.push("Only three decimal values are allowed for " + taskCurr + "<br\>");
                            finalCheck.push('false' + ',');
                            errorFieldArray.push('amendSettAmt');
                        }
                    } else if (doubleDecimalCurrencies.indexOf(taskCurr.toString()) <= -1) {
                        if (!twoDecRegex.test(amendSettAmt)) {
                            notifyUser.push("Only two decimal values are allowed for " + taskCurr + "<br\>");
                            finalCheck.push('false' + ',');
                            errorFieldArray.push('amendSettAmt');
                        }
                    }
                }
            } else {
                finalCheck.push('true' + ',');
            }

            //Trade Decimal Check
            // gs.info("amend 442 notifyUser= " + notifyUser);
            if (arrayFlag == 'true') { //MSSCUSTODY-6872
                return errorFieldArray.toString();
            } else {
                return notifyUser.toString().replaceAll(",", " ");
            }

        } catch (error) {
            gs.info("Error from AmendInputs " + error.message);
        }
    },

    regexCheck: function(inputValue) {
        var charRegex = /[^a-zA-Z0-9\s]/g;
        var finalResult = inputValue.replace(charRegex, '');
        finalResult = finalResult.trim();
        finalResult = finalResult.replace(/\s/g, '');
        return finalResult;
    },


    createSingleCaseTask: function() { //This will be triggered once the user clicks on Amend Single Trade
        //MSSCUSTODY-6077
        //UI Action -- Trigger Amend
        //Triggers the Manual Amend for a Single Trade. After triggering a New Case and Task should be created

        var amendTemplate = new global.JSON.parse(this.selectTaskTemplate('CUSTODYTTMP00126')); //Template selection

        try {
            var tradeSelected = this.getParameter('sysparm_trdID');

            var grcustodytrade = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
            var makerAssignmentGroup = this.getAssignmentGroup('x_hsb11_mss_custod.custody_maker'); // MSSCUSTODY-7378
            if (grcustodytrade.get(tradeSelected)) {
                var grcustodycase = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_case");
                grcustodycase.initialize();
                grcustodycase.short_description = 'Manually triggered';
                grcustodycase.description = 'Manually triggered - to perform Trade Amend';
                grcustodycase.trade_id = grcustodytrade.sys_id;
                grcustodycase.triggered_by = '19c79fbb1ba30a10c6ada6c7b04bcbd5';
                grcustodycase.case_status = 'ec34a3731b270a10c6ada6c7b04bcb7a';
                grcustodycase.case_type = 'manual';
                grcustodycase.insert();
                if (grcustodycase) {
                    var grcustodytask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
                    grcustodytask.initialize();
                    grcustodytask.trade_task_type = 'Maker';
                    grcustodytask.short_description = amendTemplate.shortDescription; //deparsed from method selectTaskTemplate
                    grcustodytask.description = amendTemplate.description; //deparsed from method selectTaskTemplate
                    grcustodytask.trade_task_type = amendTemplate.trdTaskType;
                    grcustodytask.trade_task_template_id = amendTemplate.templateID;
                    grcustodytask.trade_id = grcustodytrade.sys_id;
                    grcustodytask.trade_case_id = grcustodycase.sys_id;
                    grcustodytask.outcome = 'Amend Trade';
                    grcustodytask.checker_decision = 'Amend';
                    grcustodytask.setValue('assignment_group', makerAssignmentGroup); // MSSCUSTODY-7378
                    grcustodytask.setValue('assigned_to', gs.getUserID()); // MSSCUSTODY-7378
                    grcustodytask.follow_up = new GlideDateTime();
                    grcustodytask.insert();
                }
                grcustodytrade.case_type = 'manual'; //MSSCUSTODY-6108
                grcustodytrade.update();
            }
            if (grcustodytask) { //return true if Case record and Case task records are created successfully
                return grcustodytask.sys_id;
            } else
                return false; //return false if any of the records are not created
        } catch (ex) {
            gs.info("Error from script Include MSSCustodyAmendUtils - createSingleCaseTask: " + ex.message);
        }
    },

    createBulkCaseTask: function() { //This will be triggered once the user clicks on Amend Selected Trade

        var rpaTemplate = new global.JSON.parse(this.selectTaskTemplate('CUSTODYTTMP00035')); //Template selection

        /* This method is create a RPA Case and task when the user clicks on Amend Selected Trade
		Working: DB Sys ID is sent from client side and glided in the database view taking the 
		actual trade sys ID and using the trade SYS_ID
		//Due date of task is calculated using - HSBC-Updating due date with sla timer
        Currently called in UI Action : Amend Selected Trade */
        try {
            var tradeSelected = this.getParameter('sysparm_query');
            var custodyTaskID = [];
            var taskCreationFlag = false;
            var taskCreated = '';

            var grtradeDatabase = new GlideRecord("x_hsb11_mss_c_proc_custody_trades"); //Database view name
            grtradeDatabase.addEncodedQuery(tradeSelected);
            grtradeDatabase.query();
            while (grtradeDatabase.next()) {

                var grcustodytrade = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade'); //actual Trade table
                grcustodytrade.addQuery('sys_id', grtradeDatabase.custodytrade_sys_id);
                grcustodytrade.query();
                if (grcustodytrade.next()) {
                    var grcustodycase = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_case");
                    grcustodycase.initialize();
                    grcustodycase.short_description = 'Manually triggered by RPA';
                    grcustodycase.description = 'Manually triggered by RPA';
                    grcustodycase.trade_id = grcustodytrade.sys_id;
                    //grcustodycase.bulk_id = bulkID;
                    grcustodycase.triggered_by = '7da8965f1bde5a106ed00e1ad34bcb97';
                    grcustodycase.case_status = 'aad308e91bed5e106ed00e1ad34bcb79';
                    //grcustodycase.setWorkflow(false); stopping manual flow to trigger, hence commented
                    grcustodycase.insert();

                    if (grcustodycase) {
                        var grcustodytask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
                        grcustodytask.initialize();
                        grcustodytask.short_description = rpaTemplate.shortDescription; //deparsed from method selectTaskTemplate
                        grcustodytask.description = rpaTemplate.description; //deparsed from method selectTaskTemplate
                        grcustodytask.trade_task_type = rpaTemplate.trdTaskType;
                        grcustodytask.trade_task_template_id = rpaTemplate.templateID;
                        grcustodytask.trade_id = grcustodytrade.sys_id;
                        grcustodytask.trade_case_id = grcustodycase.sys_id;
                        //grcustodytask.trade_task_type = 'Maker';
                        //grcustodytask.sub_trade_task_type =  'Amend - RPA';
                        grcustodytask.outcome = 'Amend Trade';
                        grcustodytask.insert();
                        taskCreated = grcustodytask.sys_id;
                        custodyTaskID.push(taskCreated + ',');

                    }

                    taskCreationFlag = true;
                }
            }

            if (taskCreationFlag) { //return true if Bulk record, Case record and Case task records are created successfully
                return custodyTaskID.toString();
            } else
                return false; //return false if any of the records are not created
        } catch (ex) {
            var message = ex.message;
            gs.info("Error from script Include MSSCustodyBulkUtils - createManualTradeBulkID: " + message);
        }

    },

