    // MSSCUSTODY-7378
    getAssignmentGroup: function(roleName) { //MSSCUSTODY-3425
        // var assignmentGroup = '';
        var grMember = new GlideRecord('sys_user_grmember');
        grMember.addQuery('user', gs.getUserID());
        grMember.addEncodedQuery('group.typeLIKE2269529d1b844650ff37eb14b24bcb19');
        grMember.query();

        while (grMember.next()) {
            var grGroupRole = new GlideRecord('sys_group_has_role');
            grGroupRole.addQuery('group', grMember.group);
            grGroupRole.addQuery('role.name', roleName);
            grGroupRole.query();

            if (grGroupRole.next()) {
                assignmentGroup = grGroupRole.group;
                break;
            }

        }

        return assignmentGroup;


    },


    getTradeFieldvalues: function() {

        try {

            //This method is to prepropulate the amend fields for automated task when the outcome is selected as Amend related outcomes
            //Once the form is submitted, the below method executes creating a culk and associating the responses provided by user to bulk record
            var tradeID = this.getParameter('sysparm_tradeID');
            var taskID = this.getParameter('sysparm_taskID');

            var getTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
            getTask.get(taskID);

            var taskStatus = getTask.active;

            if (taskStatus) {

                var amendInputs = {};
                var getTradeData = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
                getTradeData.get(tradeID);

                var tradefieldValues = ['security_id', 'trade_date', 'settlement_date', 'deal_price', 'deal_price_currency', 'settlement_amount_currency', 'settlement_amount', 'counterparty_reference', 'customer_reference', 'location_code', 'hold_matched_si_indicator', 'script_hold_indicator', 'cash_hold_indicator', 'gdi_indicator', 'cash_payment_method', 'switch_indicator', 'switch_account', 'counterparty_code', 'receiver_deliverer_custodian_bic', 'buyer_seller_bic', 'place_of_settlement_95a_qualifier_pset', 'u_client_s_seller_buyer_account', 'convert_to_account_switching', 'counterparty_cash_account_id', 'suspense_account_number', 'amend_charges_type', 'amend_charges_ccy', 'amend_charges_amt', 'nssc', 'si_purpose_code', 'data_source_scheme', 'propriety_code', 'iss_ind', 'fa', 'switch_reference']; //populate amend values
                var requestHeaders = ['securityID', 'tradeDate', 'settlementDate', 'dealPrice', 'dealCurrency', 'settlementCurrency', 'settlementAmount', 'counterPartyRef', 'cusRef', 'locCode', 'hmiIndicator', 'scripholIndicator', 'cashHoldIndicator', 'gdiIncidcator', 'payMethod', 'switchIndicator', 'switchAcc', 'counterParCode', 'delivererCusBic', 'sellBuyBic', 'placeofSett', 'accOfClient', 'converAccSwitch', 'counterSettAccNum', 'susAccNum', 'amendChargesType', 'amendChargesCCY', 'amendChargesAmt', 'amendNSSC', 'amendPurposeCode', 'amendDataSource', 'amendProprietyCode', 'issIND', 'amendFa', 'amendTradeSwitchReference']; // request body header

                for (i = 0; i < tradefieldValues.length; i++) {

                    if ((getTradeData.getValue(tradefieldValues[i]) != '') && (getTradeData.getValue(tradefieldValues[i]) != null) && (getTradeData.getValue(tradefieldValues[i]) != undefined)) {
                        var nonNullRequestHeadersname = requestHeaders[i];
                        var nonNullTrdValue;
                        if (tradefieldValues[i].toString() == 'switch_reference') { //switch reference Handling
                            nonNullTrdValue = getTradeData.getValue(tradefieldValues[i])
                            var getSwitchReference = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
                            gs.info('Received Query ' + 'transaction_referenceSTARTSWITH' + nonNullTrdValue + '^owning_business=' + getTradeData.owning_business)
                            getSwitchReference.addEncodedQuery('transaction_referenceSTARTSWITH' + nonNullTrdValue + '^owning_business=' + getTradeData.owning_business);
                            getSwitchReference.setLimit(1);
                            getSwitchReference.query();
                            if (getSwitchReference.next()) {
                                nonNullTrdValue = getSwitchReference.getValue('trade_id');
                                gs.info('TradeID Amend ' + nonNullTrdValue)
                            } //switch reference Handling
                            else {
                                nonNullTrdValue = "";
                            }

                        } else {
                            nonNullTrdValue = getTradeData.getValue(tradefieldValues[i]);
                        }
                        amendInputs[nonNullRequestHeadersname] = nonNullTrdValue;

                    } else {
                        var nullRequestHeadersname = requestHeaders[i];
                        amendInputs[nullRequestHeadersname] = '';
                    }
                }
                gs.info('Amend INputs ' + JSON.stringify(amendInputs));


                return JSON.stringify(amendInputs);
            } else {

                return false;
            }

        } catch (error) {
            gs.info("Error from AmendInputs getTradeFieldvalues" + error.message);
        }


    },




    getRPABotIDfroBulk: function(ghssHandlerTask) {

        try {

            var getTradeID = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
            getTradeID.get(ghssHandlerTask); //need to pass current ssys ID when checker task gets closed
            var bulkID = getTradeID.bulk_id.sys_id;
            var rpaBotID = "";

            //picking up the associated maker task to find the specific record in the widget inbound
            //relation maker task sys id will be associated with Message ID in widget inbound table
            //picking up the sys id of last GHSS task which to fetch ther inbound record with RPA bot ID
            var getPreviousHandlerID = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
            getPreviousHandlerID.addEncodedQuery('trade_case_id!=NULL^trade_task_typeLIKEhandler^bulk_id.sys_idSTARTSWITH' + bulkID + '^sys_id!=' + ghssHandlerTask);
            getPreviousHandlerID.orderByDesc('sys_created_on');
            getPreviousHandlerID.setLimit(1);
            getPreviousHandlerID.query();
            if (getPreviousHandlerID.next()) {

                //Fetching the event Layer payload to pick bot ID which maker task needs approval
                var getInboundRec = new GlideRecord('x_hsb11_hsbc_mss_o_mss_widget_inbound');
                getInboundRec.addEncodedQuery('message_idSTARTSWITH' + getPreviousHandlerID.sys_id + '^event_typeSTARTSWITHEVENT_LAYER_RPA_AMEND^sourceLIKERPA^ORsourceLIKEEVENT_LAYER');
                getInboundRec.orderByDesc('sys_created_on');
                getInboundRec.setLimit(1);
                getInboundRec.query();
                if (getInboundRec.next()) {
                    var getPayload = JSON.parse(getInboundRec.payload);
                    getPayload = JSON.stringify(getPayload['rpabotid']);
                    rpaBotID = getPayload.substring(1, (getPayload.length - 1));

                }
            }
            //picking up the associated maker task to find the specific record in the widget inbound

            return rpaBotID;

        } catch (ex) {
            gs.info("Error from x_hsb11_mss_c_proc.MSSCustodyAmendUtils - getRPABotIDfroBulk : " + ex);
        }

    },

    tradeAmendMapper: function(choiceValue) {

        try {

            if (choiceValue) {

                TYPEMAPPING = {
                    'Hold by Bypass': 'B',
                    'Not Generate': 'N',
                    'Manual Generation': 'M',
                    'Auto Generation': 'A',

                };

                return TYPEMAPPING[choiceValue.toString()].toString();
            } else {
                return '';
            }

        } catch (ex) {
            gs.info('Error received from Amend Mapper ' + ex)
        }
    },


    //

    tradeAmendRegexHandler: function(inputValue, regexIdentifier) {

        try {

            var removeSpcialChars = /[^a-zA-Z0-9\s]/g;
            var finalResult = '';

            if (regexIdentifier) {
                regexIdentifier = regexIdentifier;
            } else {
                regexIdentifier = '';
            }

            switch (regexIdentifier) {
                case 'suspenseAccountNumber':
                    if (inputValue != '' && inputValue != undefined && inputValue != null) {
                        finalResult = inputValue.replace(removeSpcialChars, '');
                        finalResult = finalResult.trim();
                        finalResult = finalResult.replace(/\s/g, '');
                        var prefix = finalResult.substring(0, 3);
                        var currencyCode = finalResult.substring(3, 6);
                        var accountNumber = finalResult.substring(6, (finalResult.length + 1));
                        finalResult = prefix + " " + currencyCode + " " + accountNumber;
                        break;
                    } else {
                        finalResult = null;
                        break;
                    }

                case 'switchAccountNumber':
                    if (inputValue != '' && inputValue != undefined && inputValue != null) {
                        finalResult = inputValue.replaceAll("-", " ")
                        break;
                    } else {
                        finalResult = null;
                        break;
                    }


                case 'settlementAccountNumber':
                    if (inputValue != '' && inputValue != undefined && inputValue != null) {
                        finalResult = inputValue.replace(removeSpcialChars, '');
                        finalResult = finalResult.trim();
                        finalResult = finalResult.replace(/\s/g, '');
                        var prefix = finalResult.substring(0, 3);
                        var currencyCode = finalResult.substring(3, 6);
                        var accountNumber = finalResult.substring(6, (finalResult.length + 1));
                        finalResult = prefix + " " + currencyCode + " " + accountNumber;
                        break;
                    } else {
                        finalResult = null;
                        break;
                    }


                case 'default':
                    finalResult = '';


            }
            return finalResult;

        } catch (ex) {
            gs.info('Error Received from tradeAmendRegexHandler ' + ex);
        }
    },





