            //concatinating payloads
            reqBody['HEADER'] = headerPayload;

            if (((checkerDecision == 'Checker Approved') || (checkerDecision == 'Checker Rejected')) && (taskOutcome == 'Amend Trade')) {
                reqBody['PAYLOAD'] = checkerPayload; //sending empty payload since checker approval or rejection
            } else {
                reqBody['PAYLOAD'] = requestPayload; //sending only when checker decision is checker null
            }
            //concatinating payloads
            //creation of payload in GHSS Outbound
            var checkerTaskGR = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
            if (checkerTaskGR.get(checkerTask)) { // Pass the checker task sys_id here
                // Find the maker task related to this checker task
                var makerTaskGR = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
                makerTaskGR.addQuery('trade_case_id', checkerTaskGR.trade_case_id);
                makerTaskGR.addQuery('trade_id', checkerTaskGR.trade_id);
                makerTaskGR.addQuery('trade_task_type', 'Maker');
                makerTaskGR.orderByDesc('sys_created_on');
                makerTaskGR.query();

                if (makerTaskGR.next()) {
                    var tradeID = makerTaskGR.trade_id.trade_id;
                    var triggeredBy = makerTaskGR.trade_case_id.triggered_by.getDisplayValue();

                    var tradeGR = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
                    if (tradeGR.get(makerTaskGR.trade_id.sys_id)) {
                        reqBody['PAYLOAD'].task_id = makerTaskGR.number + '';
                        reqBody['PAYLOAD'].trade_id = tradeID.toString();
                        reqBody['PAYLOAD'].triggered_by = triggeredBy.toString();

                        var finalPayload = reqBody['PAYLOAD'];
                        var auditObj = {};
                        if (tradeGR.trade_audit) {
                            try {
                                auditObj = JSON.parse(tradeGR.trade_audit);
                            } catch (e) {
                                auditObj = {};
                            }
                        }
                        if (!Array.isArray(auditObj.amendAndConf)) {
                            auditObj.amendAndConf = [];
                        }
                        auditObj.amendAndConf.push(finalPayload);
                        tradeGR.trade_audit = JSON.stringify(auditObj);
                        tradeGR.update();
                    }
                }
            }

        } catch (ex) {
            gs.info("Error from Script Include - x_hsb11_mss_c_proc.MSSCustodyAmendUtils - createPayloadSingleTradeAmendandCONF " + ex);
        }

