    getCurrencyCodeForAmend: function(tradeSysid, input, table) {

        try {

            var finalCurrency = '';
            var glideTable = '';

            if (table == 'trade') {
                glideTable = 'x_hsb11_mss_c_proc_mss_custody_trade'
            } else if (table == 'bulk') {
                glideTable = 'x_hsb11_hsbc_mss_o_hsbc_bulk_transaction'
            }

            var getTradeId = new GlideRecord(glideTable);
            getTradeId.get(tradeSysid)

            switch (input) {
                case 'deal_price_currency':

