                if (((tradefieldValues[i] != bulkFieldValues[i]) && (bulkFieldValues[i] != '') && (bulkFieldValues[i] != null) && (bulkFieldValues[i] != undefined) && (tradefieldValues[i] != null) && (tradefieldValues[i] != undefined)) || ((tradefieldValues[i] != bulkFieldValues[i]) && (tradefieldValues[i] != '') && (tradefieldValues[i] != null) && (tradefieldValues[i] != undefined) && (bulkFieldValues[i] != null) && (bulkFieldValues[i] != undefined))) { //dynmaic JSOn creation only if the previous value in trade is diffeent than the amendment value
                    var requestHeadersNewName = requestNewHeaders[i]; //oldHeaders
                    var requestHeadersOldName = requestOldHeaders[i]; //newHeaders
                    var amendValue = bulkFieldValues[i]; //newValue
                    if (amendValue == 'NA') {
                        amendValue = '';
                    }
                    var tradevalue = tradefieldValues[i]; //oldValue
                    requestPayload[requestHeadersNewName] = amendValue; //appending the dynmaic headers and values which has undergone change // the inital headers will be passed by default // newValue
                    requestPayload[requestHeadersOldName] = tradevalue; //appending old value from trade
                }


            }
            //generation of payload for single amend //original Code

            //test code



            //concatinating payloads
            reqBody['HEADER'] = headerPayload;

            if (((checkerDecision == 'Checker Approved') || (checkerDecision == 'Checker Rejected')) && (taskOutcome == 'Amend Trade')) {
                reqBody['PAYLOAD'] = checkerPayload; //sending empty payload since checker approval or rejection
            } else {
                reqBody['PAYLOAD'] = requestPayload; //sending only when checker decision is checker null
            }
            //concatinating payloads


            //creation of payload in GHSS Outbound
            new x_hsb11_mss_c_ghss.MSSGHSSAmendUtils().createOutBoundRecSingleAmend(reqBody, ghssHandlerTask, makerID, checkerID, tradeID, tradeLastUpdated);
