    getLatestHandlerState: function() {
        var taskId = this.getParameter('sysparm_task_id');
        var latestHandlerState = '';
        var makerGR = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
        makerGR.addQuery('number', taskId);
        makerGR.query();
        if (makerGR.next()) {
            var tradeCaseId = makerGR.trade_case_id;
            var tradeId = makerGR.trade_id;
            var handlerGR = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
            handlerGR.addQuery('trade_case_id', tradeCaseId);
            handlerGR.addQuery('trade_id', tradeId);
            handlerGR.addQuery('trade_task_type', 'GHSS Handler - Amend');
            handlerGR.orderByDesc('sys_created_on');
            handlerGR.query();
            if (handlerGR.next()) {
                var widgetGR = new GlideRecord('x_hsb11_hsbc_mss_o_mss_widget_inbound');
                widgetGR.addQuery('message_id', handlerGR.sys_id);
                widgetGR.query();
                if (widgetGR.next()) {
                    var eventStatus = widgetGR.event_status + '';
                    latestHandlerState = eventStatus.replace(/_/g, ' ');
                }
            }
        }
        return latestHandlerState;
    },

