                        bulkFieldValues = [getAmendValues.security_id_sec_id.getDisplayValue()]; //populate amend values
                        requestOldHeaders = ['security_id_previous']; // request body old header
                        requestNewHeaders = ['security_id_current']; // request body new header
                        break;
                    case "amendment_charges":
                        tradefieldValues = [getTask.trade_id.amend_charges_type.getDisplayValue(), tradeAmendChargedBulk, getTask.trade_id.amend_charges_amt.getDisplayValue()]; //populate new fields
                        bulkFieldValues = [getAmendValues.amend_charges_type.getDisplayValue(), bulkAmendChargesBulk, getAmendValues.amend_charges_amt.getDisplayValue()]; //populate amend values
                        requestOldHeaders = ['amend_charges_type_previous', 'amend_charges_ccy_previous', 'amend_charges_amt_previous']; // request body old header
                        requestNewHeaders = ['amend_charges_type_current', 'amend_charges_ccy_current', 'amend_charges_amt_current']; // request body new header
                        break;
                    case "blank_trade_date":
