                // headerPayload.MessageID = taskID;
                // headerPayload.EventType = parseHeader.eventtype;
                // headerPayload.Source = parseHeader.source;
                // headerPayload.ObjectType = parseHeader.objecttype;
                // headerPayload.ObjectIDType = parseHeader.objectidtype;
                // headerPayload.ObjectID = tradeID;
                // headerPayload.ObjectVersion = parseHeader.objectversion;
                // headerPayload.EventStatus = parseHeader.eventstatus;
                // headerPayload.EventDateTime = tradeLastUpdated;
                // //initial headers Generation


                // //additional attributes
                // additionalAttribute.bulk = bulkID;
                // additionalAttribute.maker = makerID;
                // additionalAttribute.checker = checkerID;
                // additionalAttribute.reference = tradeID;
                // additionalAttribute.servicenowid = taskID;
                // additionalAttribute.owning_business = trdOwningBusiness;
                // additionalAttribute.transaction_type = tradeTransactionType;
                // additionalAttribute.legacy_sub_status = tradeLegacySubStatus;
                // additionalAttribute.last_update_date_time = tradeLastUpdated;
                // additionalAttribute.checker_decision = taskStatus;
                // additionalAttribute.rpabotid = getBotID;
                // additionalAttribute.amend_type = "amend";
                // //additional attributes



                // //headerPayload['AdditionalAttributes'] = additionalAttribute; // MSSCUSTODY-7335 Updated to AdditionalAttributes
                // headerPayload['additionalattributes'] = additionalAttribute;
            }


            //generation of payload for single amend 
            for (var i = 0; i < tradefieldValues.length; i++) {

                if (((tradefieldValues[i] != bulkFieldValues[i]) && (bulkFieldValues[i] != '') && (bulkFieldValues[i] != undefined) && (bulkFieldValues[i] != null))) {
                    var requestHeadersNewName = requestNewHeaders[i]; //oldHeaders
                    var requestHeadersOldName = requestOldHeaders[i]; //newHeaders
                    var amendValue = bulkFieldValues[i]; //newValue
                    if (amendValue == 'NA') {
                        amendValue = '';
                    }
                    var tradevalue = tradefieldValues[i]; //oldValue
                    requestPayload[requestHeadersNewName] = amendValue; //appending the dynmaic headers and values which has undergone change // the inital headers will be passed by default // newValue
                    requestPayload[requestHeadersOldName] = tradevalue; //appending old value from trade
                }
            }
            //generation of payload for single amend 

            //concatinating payloads
            // reqBody['HEADER'] = headerPayload;
            reqBody['PAYLOAD'] = requestPayload; //sending only when checker decision is checker null

            //concatinating payloads

            var bulkGR = new GlideRecord('x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
            if (bulkGR.get(bulkRec)) {
                // Assign additional payload fields
                reqBody['PAYLOAD'].task_id = ghssHandler.number + '';
                reqBody['PAYLOAD'].trade_id = ghssHandlerTask.trade_id.trade_id.toString();
                reqBody['PAYLOAD'].triggered_by = ghssHandlerTask.trade_case_id.triggered_by.getDisplayValue();

                var finalPayload = reqBody['PAYLOAD'];
                var auditObj = {};
                if (bulkGR.bulk_audit) {
                    try {
                        auditObj = JSON.parse(bulkGR.bulk_audit);
                    } catch (e) {
                        auditObj = {};
                    }
                }
                if (!Array.isArray(auditObj.checker_audit)) {
                    auditObj.checker_audit = [];
                }
                auditObj.checker_audit.push(finalPayload);
                bulkGR.bulk_audit = JSON.stringify(auditObj);
                bulkGR.update();
            }


            // new x_hsb11_mss_c_ghss.MSSGHSSAmendUtils().createOutBoundRecSingleAmend(reqBody, ghssHandlerTask, makerID, checkerID, tradeID, tradeLastUpdated);

