    getAmendBulkFieldLabels: function() {


        try {

            var bulk = this.getParameter('sysparm_bulkValue');
            var taskMode = this.getParameter('sysparm_taskMode');
            var getChoiceValues;
            var amendFields = gs.getProperty('x_hsb11_mss_c_proc.getfieldlabelsamend.outcomes');
            var getAmendLabels = JSON.parse(amendFields);

            if ((bulk.toString() == 'false') && (taskMode == 'automatedTask')) { //automated Task
                getAmendLabels = getAmendLabels['automatedTask'];
            } else if ((bulk.toString() == 'true') && (taskMode == 'singleBulk')) { //Single Bulk Record
                getAmendLabels = getAmendLabels['automatedTask'];
            } else if ((bulk.toString() == 'true') && (taskMode == 'trade_settl_date')) { //Trade & Sett Date
                getAmendLabels = getAmendLabels['trade_settl_date'];

            } else if ((bulk.toString() == 'true') && (taskMode == 'customer_reference')) { //Customer  Reference
                getAmendLabels = getAmendLabels['customer_reference'];
            } else if ((bulk.toString() == 'true') && (taskMode == 'location_gdi')) { //Location / GDI 
                getAmendLabels = getAmendLabels['location_gdi'];
            } else if ((bulk.toString() == 'true') && (taskMode == 'hmi_indicator​')) { //HMI Indicator​
                getAmendLabels = getAmendLabels['hmi_indicator​'];
            } else if ((bulk.toString() == 'true') && (taskMode == 'script_hold_indicator')) { //Scrip Hold Indicator
                getAmendLabels = getAmendLabels['script_hold_indicator'];
            } else if ((bulk.toString() == 'true') && (taskMode == 'cash_hold_indicator')) { //Cash Hold Indicator
                getAmendLabels = getAmendLabels['cash_hold_indicator'];
            } else if ((bulk.toString() == 'true') && (taskMode == 'counterparty_details')) { //Counterparty Details
                getAmendLabels = getAmendLabels['counterparty_details'];
            } else if ((bulk.toString() == 'true') && (taskMode == 'beneficiary_details')) { //Beneficiary Details
                getAmendLabels = getAmendLabels['beneficiary_details'];
            } else if ((bulk.toString() == 'true') && (taskMode == 'amendment_charges')) { //MSSCUSTODY 5755 - Added Amend Charges Type in Bulk field group
                getAmendLabels = getAmendLabels['amendment_charges'];
            } else if ((bulk.toString() == 'true') && (taskMode == 'security_id')) { //MSSCUSTODY 5755 - Added Security ID in Bulk field group
                getAmendLabels = getAmendLabels['security_id'];
            } else if ((bulk.toString() == 'false') && (taskMode == 'amendFieldsOnTask')) { //MSSCUSTODY 5755 - Added Security ID in Bulk field group
                getAmendLabels = getAmendLabels['amendFieldsOnTask'];
            } else if ((bulk.toString() == 'true') && (taskMode == 'hideFieldsAmend')) { //Beneficiary Details
                getAmendLabels = getAmendLabels['hideFieldsAmend'];
            } else {
                getAmendLabels = getAmendLabels['None'];
            }



            return getAmendLabels;

        } catch (ex) {
            gs.info('Error Message from getAmendBulkFieldLabels ' + ex);
        }


    },


    amendResetAllButtonVisibility: function(templateID, taskStatus, trdTaskType) {
        /*
		1) UI Action: Reset All Fields
