		3) Script Include : x_hsb11_mss_c_proc.MSSCustodyAmendUtils - Method - amendResetAllButtonVisibility
		*/

        var buttonVisibility = false;
        if (trdTaskType.toString() == 'Maker') {
            if ((taskStatus == 1) || (taskStatus == 2)) {
                var gg = new GlideRecord('x_hsb11_mss_c_proc_custody_trade_task_outcome_mapping');
                gg.addEncodedQuery('trade_template_id.sys_idSTARTSWITH' + templateID + '^outcomeLIKEamend');
                gg.query();
                if (gg.next()) {
                    buttonVisibility = true;
                }
            }
        }
        return buttonVisibility;
    },





    checkIfOutcomeHoldsAmend: function() {
        /*
		1) Client Script: Add Amend Bulk Field Group Options
    	Used to evaluate if atleast one of the outcome field contains amend as outcome
		*/
        try {

            var getBulkID = this.getParameter('sysparm_bulkID');

            var getBulkData = new GlideRecord('x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
            getBulkData.get(getBulkID);

            var templateID = getBulkData.trade_task_template_id;
            var bulkStatus = getBulkData.state;
            var bulkTaskType = getBulkData.bulk_task_type;

            var triggerEvaluation = false;
            if (bulkTaskType.toString() == 'Maker') {
                if ((bulkStatus == 1) || (bulkStatus == 2)) {
                    var gg = new GlideRecord('x_hsb11_mss_c_proc_custody_trade_task_outcome_mapping');
                    gg.addEncodedQuery('trade_template_id.sys_idSTARTSWITH' + templateID + '^outcomeLIKEamend');
                    gg.query();
                    if (gg.next()) {
                        triggerEvaluation = true;
                    }
                }
            }
            return triggerEvaluation;
        } catch (ex) {
            gs.info('Error Received from checkIfOutcomeHoldsAmend' + ex);
        }
    },

    disableAmendOutcome: function() {
        /*
		1) Client Script: Add Amend Bulk Field Group Options
    	Used to evaluate if atleast one of the outcome field contains amend as outcome
		*/
        try {

            var getBulkID = this.getParameter('sysparm_bulkID');

            var getBulkData = new GlideRecord('x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
            getBulkData.get(getBulkID);

            var templateID = getBulkData.trade_task_template_id;
            var bulkStatus = getBulkData.state;
            var bulkTaskType = getBulkData.bulk_task_type;
            var bulkMarket = getBulkData.owning_business;

            var enableAmend = false;

            if (bulkMarket.toString() == 'DCC HK') {

                if (bulkTaskType.toString() == 'Maker') {
                    if ((bulkStatus == 1) || (bulkStatus == 2)) {
                        var gg = new GlideRecord('x_hsb11_mss_c_proc_custody_trade_task_outcome_mapping');
                        gg.addEncodedQuery('trade_template_id.sys_idSTARTSWITH' + templateID + '^outcomeLIKEamend');
