    amendEvaluateIfAmended: function() {
        try {
            var charRegex = /[^a-zA-Z0-9\s]/g;
            var tradeDataArray = [];
            var tradeTaskArray = [];
            var allowAmend;
            var slashRegex = /\s/g;
            var arrayUtil = new global.ArrayUtil();


