            var taskDelivererBic = this.getParameter('sysparm_taskDelivererCusBic'); //Deliverer Bic MSSCUSTODY-7158
            var taskBuyerBic = this.getParameter('sysparm_taskBuyerBic'); //buyer Bic MSSCUSTODY-7158
            var tasksellBuyBic = this.getParameter('sysparm_taskSellerBic'); //seller Bic MSSCUSTODY-7158


