            var taskamendNSSC = this.getParameter('sysparm_taskamendNSSC');

            var taskSiPuposeCode = this.getParameter('sysparm_taskamendsipuposeCode'); //MSSCUSTODY-7294
            var taskDataSourceScheme = this.getParameter('sysparm_taskamendDataSourceScheme'); //MSSCUSTODY-7294
            var taskPropriatyCode = this.getParameter('sysparm_taskamendPropriatyCode'); //MSSCUSTODY-7294
            var taskindISS = this.getParameter('sysparm_issind'); //MSSCUSTODY-7747
            var taskSWH = this.getParameter('sysparm_swh'); //MSSCUSTODY-7747
