            var dealCurrency = getTradeDetails.deal_price_currency.toString();
            var settlementCurrency = getTradeDetails.settlement_amount_currency.toString();
            var settlementAmount = getTradeDetails.settlement_amount.toString();
            var counterPartyRef = getTradeDetails.counterparty_reference.toString();
            var cusRef = getTradeDetails.customer_reference.toString();
            var locCode = getTradeDetails.location_code.toString();
            var hmiIndicator = getTradeDetails.hold_matched_si_indicator.toString();
            var scripholIndicator = getTradeDetails.script_hold_indicator.toString();
            var cashHoldIndicator = getTradeDetails.cash_hold_indicator.toString();
            var gdiIncidcator = getTradeDetails.gdi_indicator.toString();
            var payMethod = getTradeDetails.cash_payment_method.toString();
            var switchIndicator = getTradeDetails.switch_indicator.toString();
            var switchAcc = getTradeDetails.switch_account.toString();
