            var counterSettAccNum = getTradeDetails.counterparty_cash_account_id.toString();
            var converAccSwitch = getTradeDetails.convert_to_account_switching.toString();
            var accOfClient = getTradeDetails.u_client_s_seller_buyer_account.toString();
            var amendChargesType = getTradeDetails.amend_charges_type.toString();
            var amendChargesCCY = getTradeDetails.amend_charges_ccy.toString();
            var amendChargesAmt = getTradeDetails.amend_charges_amt.toString();
            var amendNSSC = getTradeDetails.nssc.toString();

            var amendSiPuposeCode = getTradeDetails.si_purpose_code.toString(); //MSSCUSTODY-7294
            var amendDataSourceScheme = getTradeDetails.data_source_scheme.toString(); //MSSCUSTODY-7294
            var amendPropriatyCode = getTradeDetails.propriety_code.toString(); //MSSCUSTODY-7294
            var amendISSIND = getTradeDetails.iss_ind;
            var amendSWH = "";
            var amendFa = getTradeDetails.fa;
            var amendSwitchReference;

            //switch reference Handling
            var getSwitchReference = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
            getSwitchReference.addEncodedQuery('transaction_referenceSTARTSWITH' + amendSwitchReference + '^owning_business=' + getTradeDetails.owning_business);
            getSwitchReference.setLimit(1);
            getSwitchReference.query();
            if (getSwitchReference.next()) {
                amendSwitchReference = getSwitchReference.getValue('trade_id');
            }
            //switch reference Handling

            //handling special Characters
            if ((cusRef != null) && (cusRef != '') && (cusRef != undefined)) {
                cusRef = cusRef.replace(charRegex, "");
                cusRef = cusRef.replace(/\s/g, ''); //space removal
            }

            if ((susAccNum != null) && (susAccNum != '') && (susAccNum != undefined)) {
                susAccNum = susAccNum.replace(charRegex, "");
                susAccNum = susAccNum.replace(/\s/g, '');
            }

            if ((accOfClient != null) && (accOfClient != '') && (accOfClient != undefined)) {
                accOfClient = accOfClient.replace(charRegex, "");
                accOfClient = accOfClient.replace(/\s/g, '');
            }

            if ((delivererCusBic != null) && (delivererCusBic != '') && (delivererCusBic != undefined)) {
                delivererCusBic = delivererCusBic.replace(slashRegex, "");
                var tradeReceiverBic = delivererCusBic.split('/')[0]; //MSSCUSTODY-7158
                var tradeDeliverCustodianBic = delivererCusBic.split('/')[1]; //MSSCUSTODY-7158

            }

            if ((placeofSett != null) && (placeofSett != '') && (placeofSett != undefined)) {
                placeofSett = placeofSett.replace(charRegex, ""); //MSSCUSTODY-7158
                placeofSett = placeofSett.replace(/\s/g, ''); //MSSCUSTODY-7158
            }

            if ((sellBuyBic != null) && (sellBuyBic != '') && (sellBuyBic != undefined)) {
                sellBuyBic = sellBuyBic.replace(slashRegex, "");
                var tradeBuyerBic = sellBuyBic.split('/')[0];
                var tradeSellerBic = sellBuyBic.split('/')[1];

            }

            if ((counterSettAccNum != null) && (counterSettAccNum != '') && (counterSettAccNum != undefined)) {
                counterSettAccNum = counterSettAccNum.replace(charRegex, "");
                counterSettAccNum = counterSettAccNum.replace(/\s/g, '');
            }


            tradeDataArray.push(
                securityID,
                tradeDate,
                settlementDate,
                dealPrice,
                dealCurrency,
                settlementCurrency,
                settlementAmount,
                counterPartyRef,
                cusRef,
                locCode,
                hmiIndicator,
                scripholIndicator,
                cashHoldIndicator,
                gdiIncidcator,
                payMethod,
                switchIndicator,
                switchAcc,
                counterParCode,
                tradeReceiverBic,
                tradeDeliverCustodianBic,
                tradeBuyerBic,
                tradeSellerBic,
                placeofSett,
                susAccNum,
                counterSettAccNum,
                converAccSwitch,
                accOfClient,
                amendChargesType,
                amendChargesCCY,
                amendChargesAmt,
                amendNSSC,
                amendSiPuposeCode,
                amendDataSourceScheme,
                amendPropriatyCode,
                amendISSIND,
                amendSWH,
                amendFa,
                amendSwitchReference

            );
            tradeTaskArray.push(
                tasksecurityID,
                tasktradeDate,
                tasksettlementDate,
                taskdealPrice,
                taskdealCurrency,
                tasksettlementCurrency,
                tasksettlementAmount,
                taskcounterPartyRef,
                taskcusRef,
                tasklocCode,
                taskhmiIndicator,
                taskscripholIndicator,
                taskcashHoldIndicator,
                taskgdiIncidcator,
                taskpayMethod,
                taskswitchIndicator,
                taskswitchAcc,
                taskcounterParCode,
                taskReceiverBic,
                taskDelivererBic,
                taskBuyerBic,
                tasksellBuyBic,
                taskplaceofSett,
                tasksusAccNum,
                taskcounterSettAccNum,
                taskconverAccSwitch,
                taskaccOfClient,
                taskamendChargesType,
                taskamendChargesCCY,
                taskamendChargesAMT,
                taskamendNSSC,
                taskSiPuposeCode,
                taskDataSourceScheme,
                taskPropriatyCode,
                taskindISS,
                taskSWH,
                taskFa,
                taskSwitchReference

            );

            tradeDataArray = tradeDataArray.filter(Boolean);
            tradeTaskArray = tradeTaskArray.filter(Boolean);
            var diff1 = arrayUtil.diff(tradeTaskArray, tradeDataArray);
            var diff2 = arrayUtil.diff(tradeDataArray, tradeTaskArray);
            var unionDiff = arrayUtil.union(diff1, diff2);



            if (unionDiff.length === 0) {
                allowAmend = false;
            } else {
                allowAmend = true;
            }
            return allowAmend;

        } catch (ex) {

            gs.info('Error from validation ' + ex);
        }

    },

