    getMakerTaskNumber: function() {
        var checkerSysId = this.getParameter('sysparm_checkerTaskId');
        var gr = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task'); // Replace with your table name
        if (gr.get(checkerSysId)) {

            var checkerCreated = gr.sys_created_on;
            var checkerTrade = gr.trade_id.sys_id.toString();
            var checkercase = gr.trade_case_id.sys_id.toString();
            // Find the maker task created just before the checker task
            var makerGR = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
            makerGR.addQuery('sys_created_on', '<', checkerCreated);
            makerGR.addQuery("trade_task_type", "Maker");
            makerGR.addQuery('trade_case_id', checkercase);
            makerGR.addQuery('trade_id', checkerTrade);
            makerGR.orderByDesc('sys_created_on');
            makerGR.query();
            if (makerGR.next()) {
                return makerGR.number.toString();
            }
        }
    },

