    //MSSCUSTODY-7266 - For Transaction Reference 
    getEligibleTrades: function(tradeMarket, settlementDate, txType, secId, quantity, secAccnt, locCode) {
        try {

            var trades = [];
            var currTxType = "";
            switch (txType ? txType.toString() : "") {

                case 'RVP':
                    currTxType = 'DVP'
                    break;

                case 'DVP':
                    currTxType = 'RVP'
                    break;

                case 'RFP':
                    currTxType = 'DFP'
                    break;

                case 'DFP':
                    currTxType = 'RFP'
                    break;
            }


            var tradeGr = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
            tradeGr.addEncodedQuery('owning_business=' + tradeMarket + '^switch_referenceISEMPTY^legacy_statusINPCON,CONF^' + 'settlement_dateON' + settlementDate + "@javascript:gs.dateGenerate('" + settlementDate + "','start')@javascript:gs.dateGenerate('" + settlementDate + "','end')" + '^settlement_quantity=' + quantity + '^security_id=' + secId + '^location_code.sys_idSTARTSWITH' + locCode + '^transaction_type=' + currTxType + '^securities_account!=' + secAccnt);
            tradeGr.query();
            while (tradeGr.next()) {
                trades.push(tradeGr.sys_id.toString());
            }
            return 'sys_idIN' + trades;

        } catch (e) {
            gs.error('Error in Script Include MSSCustodyBulkUtils, getEligibleTrades: ' + e.message);
        }
    },

