    createPayloadLinkSwitch: function(bulkRec, ghssHandlerTask) {
        try {
            var reqBody = {};
            var headerPayload = {};
            var additionalAttribute = {};
            var requestPayload = {};
            var ghssSourceSystem = gs.getProperty('x_hsb11_mss_c_ghss.hsbcGHSSWidgetTriggerSourceSystem');
