            var eventLayerHeaderParameters = gs.getProperty('x_hsb11_mss_c_proc.switchRequestHeaderParameters');
            var parseHeader = JSON.parse(eventLayerHeaderParameters);


            var getTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
            getTask.get(ghssHandlerTask);
            if (getTask.get(ghssHandlerTask)) {
                gs.info('Fetched GHSS Handler Task: ' + ghssHandlerTask);
                var taskID = ghssHandlerTask.toString();
                var makerID = 'true';
                var checkerID = 'true';
                var tradeID = getTask.trade_id.getDisplayValue();
                var sourceSystem = getTask.trade_id.source_system.toString();
                var trdOwningBusiness = getTask.trade_id.owning_business.toString();
                var tradeLastUpdated = '';
                var bulkID = 'false';
                var taskType = getTask.trade_task_type.toString();
                var getBotID = this.getRPABotIDfroBulk(ghssHandlerTask).toString(); //RPA Bot ID
                var tradeTransactionType = getTask.trade_id.transaction_type.getDisplayValue();
                tradeTransactionType = tradeTransactionType.substring(0, tradeTransactionType.split('-')[0].length).replace(" ", "");
                var outcome = getTask.outcome.toString();
                var subOutcome = getTask.bulk_id.sub_outcome.toString();
                //var counterpartyCode = getTask.bulk_id.amend_counterparty_code_ref.toString();
                var counterpartyCode = getTask.bulk_id.switch_counterparty_code.toString();
                var switchRef = getTask.bulk_id.pair_switch_reference.toString();
                var transactionRef = getTask.bulk_id.transaction_reference.getDisplayValue().split('-').slice(2, 6).join('-');

                var linkRef = getTask.bulk_id.transaction_reference_link.getDisplayValue().split('-').slice(2, 6).join('-');
                var tradeRef = getTask.bulk_id.trade_transaction_reference.toString();
                var gdi = this.tradeAmendMapper(getTask.bulk_id.amend_gdi_indicator.toString());
                var hold = getTask.bulk_id.amend_cash_hold_indicator.toString();
                var settle = getTask.bulk_id.settle_link.toString();
                var tradLinkRef = getTask.trade_id.link_reference.toString();

                if ((gcsSourceSystem.indexOf(sourceSystem) > -1) && (trdOwningBusiness.indexOf('UK') > -1)) {
                    tradeLastUpdated = getTask.trade_id.source_system_time_stamp_market_time.replace(' ', 'T').split('.')[0].toString();
                } else if ((ghssSourceSystem.indexOf(sourceSystem) > -1) && (trdOwningBusiness.indexOf('UK') == -1)) {
                    tradeLastUpdated = getTask.trade_id.source_system_time_stamp_market_time.toString();
                }
            }

            //Header Generation
            headerPayload.MessageID = taskID; //GHSS taskID;
            headerPayload.EventType = parseHeader.eventtype;
            headerPayload.Source = parseHeader.source;
            headerPayload.ObjectType = parseHeader.objecttype;
            headerPayload.ObjectIDType = parseHeader.objectidtype;
            headerPayload.ObjectID = tradeID;
            headerPayload.ObjectVersion = parseHeader.objectversion;
            headerPayload.EventStatus = parseHeader.eventstatus;
            headerPayload.EventDateTime = tradeLastUpdated;
            //Header Generation

            //Additional Attributes 
            additionalAttribute.bulk = bulkID;
            additionalAttribute.reference = tradeID;
            additionalAttribute.servicenowid = taskID; //GHSS taskID;
            additionalAttribute.owning_business = trdOwningBusiness;
            additionalAttribute.transaction_type = tradeTransactionType;
            additionalAttribute.last_update_date_time = tradeLastUpdated;
            if (outcome === 'Linking') { //MSSCUSTODY-8164
                if (subOutcome === 'Link Trade') {
                    additionalAttribute.link_maintenance = "A";
                } else if (subOutcome === 'De-Link Trades') {
                    // additionalAttribute.link_maintenance = "D";
                    // var dTransRefs = bulkRec.d_transaction_reference.toString().split(','); // Ensure array
                    // if (dTransRefs.length === 1) {
                    //     additionalAttribute.link_maintenance = "D";
                    // } else {
                    //     additionalAttribute.link_maintenance = "C";
                    // }
                    var dTransRefs = bulkRec.d_transaction_reference.toString().split(',');
                    var totalPossible = [];
                    var grAll = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
                    grAll.addQuery('link_reference', tradLinkRef);
                    grAll.query();
                    while (grAll.next()) {
                        totalPossible.push(grAll.sys_id.toString());
                    }
                    // If all except one are selected
                    if (dTransRefs.length === totalPossible.length - 1) {
                        additionalAttribute.link_maintenance = "D";
                    } else {
                        additionalAttribute.link_maintenance = "C";
                    }
                } else if (subOutcome === 'Self De-Link Trade') {
                    additionalAttribute.link_maintenance = "A";
                }
            }
            additionalAttribute.rpabotid = getBotID;

            if (outcome === 'Switch Maintenance') {
                additionalAttribute.amend_type = "switch";
            } else {
                additionalAttribute.amend_type = "link";
            }
            if (outcome === 'Linking') { //MSSCUSTODY-8164
                if (subOutcome === 'Link Trade') {
                    additionalAttribute.link_type = 'Link';
                } else if (subOutcome === 'De-Link Trades') {
                    additionalAttribute.link_type = 'De-Link';
                } else if (subOutcome === 'Self De-Link Trade') {
                    additionalAttribute.link_type = 'Self De-Link';
                }
            }

            if (subOutcome === 'Pair Trade') {
                additionalAttribute.switch_maintenance = "pair";
            } else if (subOutcome === 'De-Pair Trade') {
                additionalAttribute.switch_maintenance = "depair";
            } else if (subOutcome === 'Convert to Non-Switching Trade') {
                additionalAttribute.switch_maintenance = "convert";
            }

            //Additional Attributes

            headerPayload['additionalattributes'] = additionalAttribute;

            //Payload Generation
            if (subOutcome === 'Pair Trade') {
                requestPayload.transaction_reference = transactionRef;
            } else if (subOutcome === 'De-Pair Trade') {
                requestPayload.transaction_reference = switchRef;
            } else if (subOutcome === 'Convert to Non-Switching Trade') {
                requestPayload.transaction_reference = counterpartyCode;
            } else if (subOutcome === 'Link Trade') {

                if (linkRef.startsWith('R')) {
                    requestPayload.link_r_refs = linkRef;
                    requestPayload.link_d_refs = tradeRef;

                } else if (linkRef.startsWith('D')) {
                    requestPayload.link_r_refs = tradeRef;
                    requestPayload.link_d_refs = linkRef;
                }
                requestPayload.gdi = gdi;
                requestPayload.hold = hold;
                requestPayload.settle = settle;
            } else if (subOutcome === 'Self De-Link Trade') {
                if (tradeRef.startsWith('R')) {
                    requestPayload.link_r_refs = tradeRef;
                } else if (tradeRef.startsWith('D')) {
                    requestPayload.link_d_refs = tradeRef;
                }

                if (trdOwningBusiness === 'DCC HK') {
                    requestPayload.gdi = "";
                } else {
                    requestPayload.gdi = "N";
                }
                requestPayload.hold = "N";
                requestPayload.settle = "";

            } else if (subOutcome === 'De-Link Trades') {
                var dTransRefs = bulkRec.d_transaction_reference.toString().split(',');
                var totalPossible = [];
                var grAll = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
                grAll.addQuery('link_reference', tradLinkRef);
                grAll.query();
                while (grAll.next()) {
                    totalPossible.push(grAll.sys_id.toString());
                }
                // If all except one are selected
                if (dTransRefs.length === totalPossible.length - 1) {
                    requestPayload.link_reference = tradLinkRef;
                } else {
                    var rRefsArr = [];
                    var dRefsArr = [];
                    var tradeTransRef = bulkRec.trade_transaction_reference.toString();
                    if (tradeTransRef.startsWith('R')) {
                        rRefsArr.push(tradeTransRef);
                    } else if (tradeTransRef.startsWith('D')) {
                        dRefsArr.push(tradeTransRef);
                    }
                    for (var i = 0; i < dTransRefs.length; i++) {
                        var gr = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
                        if (gr.get(dTransRefs[i])) {
                            var transRef = gr.transaction_reference.toString();
                            if (transRef.startsWith('R')) {
                                rRefsArr.push(transRef);
                            } else if (transRef.startsWith('D')) {
                                dRefsArr.push(transRef);
                            }
                        }
                    }
                    requestPayload.link_r_refs = rRefsArr.join(',');
                    requestPayload.link_d_refs = dRefsArr.join(',');
                    requestPayload.link_reference = tradLinkRef;
                }
            }

            //Payload Generation

            reqBody.HEADER = headerPayload;
            reqBody.PAYLOAD = requestPayload;
            gs.info('Final request body: ' + JSON.stringify(reqBody));

            //Creation of Payload in GHSS Outbound 
            new x_hsb11_mss_c_ghss.MSSGHSSAmendUtils().createOutBoundRecSingleSwitch(reqBody, ghssHandlerTask, tradeID, tradeLastUpdated);
            //Creation of Payload in GHSS Outbound


        } catch (ex) {
            gs.info('Error recieved from MSSCustodyAmendUtils.createPayloadLinkSwitch : ' + ex);
        }

    },

    //MSSCUSTODY-8202 Create outbound payload for hold and canc
    createPayloadHoldAndCanc: function(bulkRec, ghssHandlerTask, taskStatus) {
        try {
            var reqBody = {};
            var headerPayload = {};
            var additionalAttribute = {};
            var requestPayload = {};
            var ghssSourceSystem = gs.getProperty('x_hsb11_mss_c_ghss.hsbcGHSSWidgetTriggerSourceSystem');
            var gcsSourceSystem = gs.getProperty('x_hsb11_mss_c_ghss.hsbcGCSWidgetTriggerSourceSystem');
            var eventLayerHeaderParameters = gs.getProperty('x_hsb11_mss_c_proc.switchRequestHeaderParameters');
            var parseHeader = JSON.parse(eventLayerHeaderParameters);


            var getTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
            getTask.get(ghssHandlerTask);
            if (getTask.get(ghssHandlerTask)) {
                gs.info('Fetched GHSS Handler Task: ' + ghssHandlerTask);
                var taskID = ghssHandlerTask.toString();
                var makerID = 'true';
                var checkerID = 'true';
                var tradeID = getTask.trade_id.getDisplayValue();
                var sourceSystem = getTask.trade_id.source_system.toString();
                var trdOwningBusiness = getTask.trade_id.owning_business.toString();
                var tradeLastUpdated = '';
                var bulkID = 'false';
                var taskType = getTask.trade_task_type.toString();
                var getBotID = this.getRPABotIDfroBulk(ghssHandlerTask).toString(); //RPA Bot ID
                var outcome = getTask.outcome.toString();
                // var subOutcome = getTask.bulk_id.sub_outcome.toString();
                var tradeTransactionType = getTask.trade_id.transaction_type.getDisplayValue();
                tradeTransactionType = tradeTransactionType.substring(0, tradeTransactionType.split('-')[0].length).replace(" ", "");
                //var counterpartyCode = getTask.bulk_id.amend_counterparty_code_ref.toString();

                if ((gcsSourceSystem.indexOf(sourceSystem) > -1) && (trdOwningBusiness.indexOf('UK') > -1)) {
                    tradeLastUpdated = getTask.trade_id.source_system_time_stamp_market_time.replace(' ', 'T').split('.')[0].toString();
                } else if ((ghssSourceSystem.indexOf(sourceSystem) > -1) && (trdOwningBusiness.indexOf('UK') == -1)) {
                    tradeLastUpdated = getTask.trade_id.source_system_time_stamp_market_time.toString();
                }
            }


            //Header Generation
            headerPayload.MessageID = taskID; //GHSS taskID;
            headerPayload.EventType = parseHeader.eventtype;
            headerPayload.Source = parseHeader.source;
            headerPayload.ObjectType = "PAPP_REQUEST";
            headerPayload.ObjectIDType = parseHeader.objectidtype;
            headerPayload.ObjectID = tradeID;
            headerPayload.ObjectVersion = parseHeader.objectversion;
            headerPayload.EventStatus = "PAPP_REQUEST_GENERATED";
            headerPayload.EventDateTime = tradeLastUpdated;
            //Header Generation

            //Additional Attributes 
            additionalAttribute.bulk = bulkID;
            additionalAttribute.reference = tradeID;
            additionalAttribute.servicenowid = taskID; //GHSS taskID;
            additionalAttribute.owning_business = trdOwningBusiness;
            additionalAttribute.transaction_type = tradeTransactionType;
            additionalAttribute.last_update_date_time = tradeLastUpdated;
            additionalAttribute.checker_decision = "CHECKER APPROVED";
            additionalAttribute.rpabotid = getBotID;
            additionalAttribute.amend_type = "pappap";

            //Additional Attributes

            headerPayload['additionalattributes'] = additionalAttribute;

            //Payload Generation
            if (outcome === 'PAPP Approval - Canc') {
                requestPayload.payload_action = "RCN";
            } else if (outcome === 'PAPP Approval - Hold') {
                requestPayload.payload_action = "RHG";
            }
            reqBody.HEADER = headerPayload;
            reqBody.PAYLOAD = requestPayload;
            gs.info('Final request body: ' + JSON.stringify(reqBody) + 'for handler : ' + getTask.number.toString());

            //Creation of Payload in GHSS Outbound 
            new x_hsb11_mss_c_ghss.MSSGHSSAmendUtils().createOutBoundRecHoldAndCanc(reqBody, ghssHandlerTask, tradeID, tradeLastUpdated);
            //Creation of Payload in GHSS Outbound


        } catch (ex) {
            gs.info('Error recieved from MSSCustodyAmendUtils.createPayloadHoldAndCanc : ' + ex);
        }

    },




    type: 'MSSCustodyAmendUtils'
});
